{
  "version": "2.0.0",
  "inputs": [
    {
      "id": "vg_target",
      "type": "pickString",
      "description": "选择构建目标预设",
      "default": "net",
      "options": [
        "net",
        "min",
        "lvgl"
      ]
    }
  ],
  "tasks": [
    {
      "label": "openvela: Release ST-LINK (kill stale OpenOCD)",
      "type": "process",
      "command": "bash",
      "args": [
        "-lc",
        "exec bash ${workspaceFolder}/scripts/wsl_kill_openocd.sh"
      ],
      "problemMatcher": []
    },
    {
      "label": "openvela: reopen workspace in WSL for IntelliSense (Cursor)",
      "type": "process",
      "windows": {
        "command": "powershell.exe",
        "args": [
          "-NoProfile",
          "-ExecutionPolicy",
          "Bypass",
          "-File",
          "${workspaceFolder}\\scripts\\windows_open_cursor_wsl.ps1"
        ]
      },
      "linux": {
        "command": "bash",
        "args": [
          "-lc",
          "echo 'Already in WSL. Command Palette → Developer: Reload Window, then clangd: Restart language server.'"
        ]
      },
      "problemMatcher": []
    },
    {
      "label": "openvela: Build (velaguard)",
      "type": "process",
      "windows": {
        "command": "wsl.exe",
        "args": [
          "-d",
          "Debian",
          "bash",
          "-lc",
          "exec bash ${workspaceFolder}/scripts/build_minimal.sh ${input:vg_target}"
        ]
      },
      "linux": {
        "command": "bash",
        "args": [
          "-lc",
          "exec bash ${workspaceFolder}/scripts/build_minimal.sh ${input:vg_target}"
        ]
      },
      "group": {
        "kind": "build",
        "isDefault": true
      },
      "problemMatcher": "$gcc"
    },
    {
      "label": "openvela: Rebuild All (velaguard)",
      "type": "process",
      "windows": {
        "command": "wsl.exe",
        "args": [
          "-d",
          "Debian",
          "bash",
          "-lc",
          "exec bash ${workspaceFolder}/scripts/build_minimal.sh ${input:vg_target} --clean"
        ]
      },
      "linux": {
        "command": "bash",
        "args": [
          "-lc",
          "exec bash ${workspaceFolder}/scripts/build_minimal.sh ${input:vg_target} --clean"
        ]
      },
      "group": "build",
      "problemMatcher": "$gcc"
    },
    {
      "label": "openvela: Flash (CubeProgrammer)",
      "type": "process",
      "windows": {
        "command": "powershell.exe",
        "args": [
          "-NoProfile",
          "-ExecutionPolicy",
          "Bypass",
          "-File",
          "${workspaceFolder}\\scripts\\windows_flash_cube.ps1",
          "-NoBuild"
        ]
      },
      "linux": {
        "command": "bash",
        "args": [
          "-lc",
          "echo 'Flash runs on Windows host. Use Cursor on Windows + CubeProgrammer, or run scripts/windows_flash_cube.ps1 from PowerShell.' >&2; exit 1"
        ]
      },
      "problemMatcher": []
    },
    {
      "label": "openvela: Build & Flash (velaguard)",
      "dependsOn": [
        "openvela: Build (velaguard)",
        "openvela: Flash (CubeProgrammer)"
      ],
      "dependsOrder": "sequence",
      "problemMatcher": []
    }
  ]
}
